mapper.select:
SELECT in_tb.*, (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD01' AND z.code = in_tb.proc_status ) AS proc_status_nm, /* 처리상태 명칭 */ ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD04' AND z.code = in_tb.inportance ) AS inportance_nm, /* 중요도 명칭 */ ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR02' AND z.code = in_tb.system_type ) AS SYSTEM_TYPE_NM, ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'OPERATE' AND z.p_code = system_type AND z.code = in_tb.inquiry_type) AS inquiry_TYPE_NM, TO_CHAR(TO_DATE(in_tb.accept_dt,'yyyyMMdd'),'yyyy-MM-dd') accept_dt, 1 FROM ( SELECT a.as_no, a.cn_as_no, a.apply_nm, a.proc_status, /* 처리상태 C */ a.cust_code, /* 거래처 코드 (cust_code) */ b.cust_kor_name, /* 거래처명 */ a.accept_route, /* 접수경로 C */ a.inportance, /* 중요도 C */ a.cause_type, /* 원인유형 C */ a.action_type, /* 조치유형 C */ a.assign_id, /* 처리담당자 아이디 */ a.call_content, /* 요청내용 */ a.OPER_SEQ, b.erp_code, nvl(( SELECT z.emp_nm FROM crm_emp_mgt z WHERE z.emp_no = a.assign_id ),'-') emp_nm, /* 처리담당자 이름 */ A.system_type, A.inquiry_type, C.system_nm, A.accept_dt FROM crm_as_mgt a , crm_cust_mgt b, crm_operate_mgt c WHERE 1=1 AND a.cust_code = b.erp_code AND A.OPER_SEQ = C.OPER_SEQ AND (A.DEL_YN IS NULL OR A.DEL_YN = 'N') AND A.ASSIGN_ID = #{reg_id} AND A.ACCEPT_DT = TO_CHAR(SYSDATE, 'YYYYMMDD') AND A.PROC_STATUS NOT IN('C006','C007')
AND B.CUST_GUBUN = #{cust_gubun}
) in_tb

SELECT A.AS_NO ,(SELECT EMP_NAME FROM CRM_CUST_EMP E WHERE E.EMP_ID= A.W_ID) AS W_NM ,A.W_CONTENT ,TO_CHAR(A.W_DATE,'YYYY-MM-DD HH24:MI:SS') AS W_DATE ,A.W_GUBUN ,M.APPLY_NM ,C.CUST_KOR_NAME ,M.CALL_CONTENT ,A.A_SEQ FROM CRM_AS_MGT_ANSWER A, CRM_AS_MGT M, CRM_CUST_MGT C WHERE 1=1 AND TO_CHAR(A.W_DATE,'YYYYMMDD') = TO_CHAR(SYSDATE,'YYYYMMDD') AND A.W_GUBUN = 'U' AND A.AS_NO = M.AS_NO AND M.CUST_CODE = C.ERP_CODE AND M.ASSIGN_ID = #{reg_id}
AND C.CUST_GUBUN = #{cust_gubun}
ORDER BY A.W_DATE DESC

SELECT * FROM(SELECT M.OPER_SEQ ,C.CUST_KOR_NAME ,C.ERP_CODE ,W.MASTER_YN ,M.SYSTEM_NM ,W.TASK_CODE ,W.WK_EMP_NO ,W.IS_USE ,(SELECT C.CODE_NAME FROM CRM_CODE_DETAIL C WHERE C.CODE_GROUP='COMMON' AND C.P_CODE='CD05' AND C.CODE = W.IS_USE ) IS_USE_NM ,(SELECT EMP_NM FROM CRM_EMP_MGT E WHERE 1=1 AND W.WK_EMP_NO = E.EMP_NO ) EMP_NM ,(SELECT C.CODE_NAME FROM CRM_CODE_DETAIL C WHERE C.CODE_GROUP='PROJECT' AND C.P_CODE='PR02' AND C.CODE = M.SYSTEM_CODE ) SYSTEM_CODE_NM ,(SELECT C.CODE_NAME FROM CRM_CODE_DETAIL C WHERE C.CODE_GROUP='OPERATE' AND C.P_CODE=M.SYSTEM_CODE AND C.CODE = W.TASK_CODE ) TASK_CODE_NM FROM CRM_OPERATE_WORKER W , CRM_OPERATE_MGT M , CRM_CUST_MGT C WHERE 1=1 AND M.OPER_SEQ = W.OPER_SEQ AND M.CUST_SEQ = C.SEQ AND M.STATE_TYPE NOT IN('C003','C004') AND C.DEAL_CODE NOT IN ('C004','C005') )IN_TB WHERE 1=1
AND WK_EMP_NO = #{reg_id}
AND C.CUST_GUBUN = #{cust_gubun}
AND( UPPER(EMP_NM) LIKE '%'|| UPPER(#{search_text}) ||'%' OR WK_EMP_NO LIKE '%'|| UPPER(#{search_text}) ||'%' )

SELECT AS_NO FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE 1=1 AND A.CUST_CODE = B.ERP_CODE AND SUBSTR(A.ACCEPT_DT,1,6) = TO_CHAR(SYSDATE,'YYYYMM') AND (A.DEL_YN IS NULL OR A.DEL_YN = 'N') AND A.PROC_STATUS NOT IN('C007','C006')
AND A.INPORTANCE ='C001' AND A.ASSIGN_ID = #{reg_id}
AND B.CUST_GUBUN = #{cust_gubun}

SELECT YYYYMM ,C001 + C002 + C003 + C004 AS flag1 ,C005 AS flag2 FROM( SELECT YYYYMM ,NVL(SUM(DECODE(PROC_STATUS,'C001',1,0)),0) AS C001 ,NVL(SUM(DECODE(PROC_STATUS,'C002',1,0)),0) AS C002 ,NVL(SUM(DECODE(PROC_STATUS,'C003',1,0)),0) AS C003 ,NVL(SUM(DECODE(PROC_STATUS,'C004',1,0)),0) AS C004 ,NVL(SUM(DECODE(PROC_STATUS,'C005',1,0)),0) AS C005 ,NVL(SUM(DECODE(PROC_STATUS,'C006',1,0)),0) AS C006 ,NVL(SUM(DECODE(PROC_STATUS,'C007',1,0)),0) AS C007 FROM ( SELECT substr(A.ACCEPT_DT,1,6) AS YYYYMM ,PROC_STATUS FROM CRM_AS_MGT A , CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -4),'YYYYMM') AND TO_CHAR(SYSDATE,'YYYYMM') /* 현월 */ AND A.CUST_CODE = B.ERP_CODE
AND B.CUST_GUBUN = #{cust_gubun}
AND A.CUST_CODE = #{cust_code}
) GROUP BY YYYYMM ORDER BY YYYYMM DESC )


 SELECT ERP_CODE, CUST_KOR_NAME, SEQ FROM CRM_CUST_MGT



	WHERE 1=1
	AND CUST_GUBUN = #{cust_gubun}

SELECT YYYYMM ,SUM(SOO1) AS SOO1 ,SUM(SOO2) AS SOO2 FROM( SELECT YYYYMM ,DECODE(SYSTEM_TYPE,'S001',1,0) AS SOO1 /*SYSTEM TYPE*/ ,DECODE(SYSTEM_TYPE,'S002',1,0) AS SOO2 FROM( SELECT substr(A.ACCEPT_DT,1,6) AS YYYYMM ,system_type FROM CRM_AS_MGT A , CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -4),'YYYYMM') AND TO_CHAR(SYSDATE,'YYYYMM') /* 현월 */ AND A.CUST_CODE = B.ERP_CODE
AND B.CUST_GUBUN = #{cust_gubun}
AND A.CUST_CODE = #{cust_code}
)in_tb )out_tb GROUP BY YYYYMM ORDER BY YYYYMM DESC

SELECT YYYYMM ,SUM(COO1) AS COO1
,SUM(COO2) AS COO2 FROM( SELECT YYYYMM ,DECODE(ACTION_TYPE,'C001',1,0) AS COO1 /*action TYPE*/ ,DECODE(ACTION_TYPE,'C002',1,0) AS COO2 /*action TYPE*/ FROM( SELECT substr(A.ACCEPT_DT,1,6) AS YYYYMM ,ACTION_TYPE FROM CRM_AS_MGT A , CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, -4),'YYYYMM') AND TO_CHAR(SYSDATE,'YYYYMM') /* 현월 */ AND A.CUST_CODE = B.ERP_CODE
AND B.CUST_GUBUN = #{cust_gubun}
AND A.CUST_CODE = #{cust_code}
)in_tb )out_tb GROUP BY YYYYMM ORDER BY YYYYMM DESC

SELECT C_COUNT ,CUST_CODE ,YYYYMM ,CUST_KOR_NAME FROM(SELECT COUNT(A.CUST_CODE) AS C_COUNT,CUST_CODE, substr(A.ACCEPT_DT,1,6) YYYYMM, B.CUST_KOR_NAME FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND A.CUST_CODE = B.ERP_CODE(+) AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) = TO_CHAR(ADD_MONTHS(SYSDATE, -4),'YYYYMM')
AND B.CUST_GUBUN = #{cust_gubun}
GROUP BY A.CUST_CODE, SUBSTR(A.ACCEPT_DT,1,6),B.CUST_KOR_NAME ORDER BY C_COUNT DESC )WHERE 1=1 AND ROWNUM < 6
UNION SELECT C_COUNT ,CUST_CODE ,YYYYMM ,CUST_KOR_NAME FROM(SELECT COUNT(A.CUST_CODE) AS C_COUNT,CUST_CODE, substr(A.ACCEPT_DT,1,6) YYYYMM , B.CUST_KOR_NAME FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND A.CUST_CODE = B.ERP_CODE(+) AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) = TO_CHAR(ADD_MONTHS(SYSDATE, -3),'YYYYMM')
AND B.CUST_GUBUN = #{cust_gubun}
GROUP BY A.CUST_CODE, substr(A.ACCEPT_DT,1,6),B.CUST_KOR_NAME ORDER BY C_COUNT DESC ) WHERE 1=1 AND ROWNUM < 6 UNION SELECT C_COUNT ,CUST_CODE ,YYYYMM ,CUST_KOR_NAME FROM(SELECT COUNT(A.CUST_CODE) AS C_COUNT,CUST_CODE, substr(A.ACCEPT_DT,1,6) YYYYMM, B.CUST_KOR_NAME FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND A.CUST_CODE = B.ERP_CODE(+) AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) = TO_CHAR(ADD_MONTHS(SYSDATE, -2),'YYYYMM')
AND B.CUST_GUBUN = #{cust_gubun}
GROUP BY A.CUST_CODE, substr(A.ACCEPT_DT,1,6),B.CUST_KOR_NAME ORDER BY C_COUNT DESC ) WHERE 1=1 AND ROWNUM < 6 UNION SELECT C_COUNT ,CUST_CODE ,YYYYMM ,CUST_KOR_NAME FROM(SELECT COUNT(A.CUST_CODE) AS C_COUNT,CUST_CODE, substr(A.ACCEPT_DT,1,6) YYYYMM, B.CUST_KOR_NAME FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND A.CUST_CODE = B.ERP_CODE(+) AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYYMM')
AND B.CUST_GUBUN = #{cust_gubun}
GROUP BY A.CUST_CODE, substr(A.ACCEPT_DT,1,6),B.CUST_KOR_NAME ORDER BY C_COUNT DESC ) WHERE 1=1 AND ROWNUM < 6 UNION SELECT C_COUNT ,CUST_CODE ,YYYYMM ,CUST_KOR_NAME FROM(SELECT COUNT(A.CUST_CODE) AS C_COUNT,CUST_CODE, substr(A.ACCEPT_DT,1,6) YYYYMM, B.CUST_KOR_NAME FROM CRM_AS_MGT A, CRM_CUST_MGT B WHERE A.ACCEPT_DT IS NOT NULL AND A.CUST_CODE = B.ERP_CODE(+) AND (A.DEL_YN = 'N' OR A.DEL_YN IS NULL) AND A.CN_AS_NO IS NULL AND substr(A.ACCEPT_DT,1,6) = TO_CHAR(SYSDATE,'YYYYMM')
AND B.CUST_GUBUN = #{cust_gubun}
GROUP BY A.CUST_CODE, SUBSTR(A.ACCEPT_DT,1,6),B.CUST_KOR_NAME ORDER BY C_COUNT DESC ) WHERE 1=1 AND ROWNUM < 6 ORDER BY YYYYMM DESC

SELECT A.PRO_SEQ --PRO SEQ , A.ERP_CODE --ERPCODE , G.CUST_KOR_NAME --거래처명 , G.CUST_GUBUN --거래처명 , A.PROJECT_NM --프로젝트명 , A.SYSTEM_CODE --시스템코드 ,(SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR02' AND z.code = A.SYSTEM_CODE) AS SYSTEM_NAME , A.STATE_TYPE --상태코드 ,(SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR01' AND z.code = A.STATE_TYPE) AS PROJECT_STATUS , A.PJT_CODE --수주심의코드 , A.TERM_START_DT -- 프로젝트시작일 , A.TERM_END_DT --프로젝트종료일 , A.OPEN_DT --전산오픈일 , A.TEST_DT --최종검수일 , A.REVIEW_DT --수주심의 확정일 , A.CONTRACT_DT --계약일 , C.WORKER_NM -- PM명 FROM CRM_PROJECT_MGT A , CRM_CUST_MGT G , CRM_PROJECT_WORKER C WHERE 1=1 AND A.ERP_CODE = G.ERP_CODE AND A.PRO_SEQ = C.PRO_SEQ(+) AND C.TASK_CODE = 'C001'
AND G.CUST_GUBUN = #{cust_gubun}
--AND TO_CHAR(SYSDATE,'YYYY') BETWEEN SUBSTR(A.TERM_START_DT, 1, 4) AND SUBSTR(A.TERM_END_DT, 1, 4)

SELECT SUM(CASE WHEN COST_GUBUN = '2' OR COST_GUBUN = '1' THEN 1 ELSE 0 END) AS A1 ,SUM(CASE WHEN COST_GUBUN = '2' THEN 1 ELSE 0 END) AS A2 --무상 ,SUM(CASE WHEN COST_GUBUN = '2' AND CONTR_END_DT < TO_CHAR(SYSDATE,'YYYYMMDD') THEN 1 ELSE 0 END) AS A3 --유상지연 ,SUM(CASE WHEN COST_GUBUN = '1' THEN 1 ELSE 0 END) AS A4 --유상 ,SUM(CASE WHEN COST_GUBUN = '1' AND CONTR_END_DT < TO_CHAR(SYSDATE,'YYYYMMDD') AND TO_CHAR(SYSDATE,'YYYY') = SUBSTR(CONTR_END_DT,0,4) THEN 1 ELSE 0 END) AS A5 --계약만료 1년차 ,SUM(CASE WHEN COST_GUBUN = '1' AND CONTR_END_DT < TO_CHAR(SYSDATE,'YYYYMMDD') AND TO_CHAR(ADD_MONTHS(SYSDATE , -12) , 'YYYY') = SUBSTR(CONTR_END_DT,0,4) THEN 1 ELSE 0 END) AS A6 --계약만료 2년차 ,SUM(CASE WHEN COST_GUBUN = '1' AND CONTR_END_DT < TO_CHAR(SYSDATE,'YYYYMMDD') AND TO_CHAR(ADD_MONTHS(SYSDATE , -24) , 'YYYY') >= SUBSTR(CONTR_END_DT,0,4) THEN 1 ELSE 0 END) AS A7 --계약만료 3년차 이상
FROM( SELECT H.COST_GUBUN ,H.CUST_CODE ,E.CUST_KOR_NAME ,ITEM_GRP3 ,ITEM_GRP3_NM ,ITEM_CD ,ITEM_NM ,CONTR_ST_DT ,CONTR_END_DT ,AMT ,CUST_GUBUN ,DEAL_CODE FROM CUST_CONTRACT_HIT H, CRM_CUST_MGT E WHERE 1=1 AND H.CUST_CODE = E.ERP_CODE AND DEAL_CODE NOT IN ('C003','C004') --거래처 해지,폐지 제외
AND CUST_GUBUN = #{cust_gubun}
)IN_TB

SELECT IN_TB.CODE_NAME, IN_TB.CAUSE_TYPE AS SEARCH_TYPE2, COUNT(IN_TB.CAUSE_TYPE) AS CNT FROM ( SELECT B.CODE_NAME, A.CAUSE_TYPE FROM CRM_AS_MGT A INNER JOIN CRM_CODE_DETAIL B ON B.CODE_GROUP = 'AS' AND B.P_CODE = 'CD05' AND B.CODE = A.CAUSE_TYPE INNER JOIN CRM_CUST_MGT C ON A.CUST_CODE = C.CRM_CODE WHERE A.CAUSE_TYPE IS NOT NULL AND A.DEL_YN IS NULL
AND C.CUST_GUBUN IN ('C003' , 'C004') AND C.CUST_GUBUN = 'C002' AND C.CUST_GUBUN = 'C001' AND C.CUST_GUBUN IN ('C005' , 'C006') AND A.ACCEPT_DT LIKE TO_CHAR(SYSDATE , 'YYYYMM') || '%' AND A.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS(SYSDATE,-1), 'YYYYMM') || '%' AND A.ACCEPT_DT BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE,-2),'YYYYMM') || '01' AND TO_CHAR(LAST_DAY(SYSDATE),'YYYYMMDD')
) IN_TB GROUP BY IN_TB.CAUSE_TYPE,IN_TB.CODE_NAME

/* 대쉬보드 거래처 as 분석 */ SELECT UT.SEQ /* CUST_MGT.SEQ */ ,UT.CRM_CODE ,UT.CUST_GUBUN ,NVL((SELECT DISTINCT CODE_NAME FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'CUST' AND P_CODE='CD01' AND CODE = UT.CUST_GUBUN),'-') AS CUST_GUBUN_NM ,UT.FOUNDATION_CODE ,NVL((SELECT DISTINCT CODE_NAME FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'CUST' AND P_CODE='CD08' AND CODE = UT.FOUNDATION_CODE),'-') AS FOUNDATION_CODE_NM ,UT.CUST_NM ,UT.CNT /* 전월 AS건수 */ ,DECODE(UT.DEAL_CODE,'C002',NVL(DECODE(UT.CNT,0,'-', TO_CHAR(ROUND((VW1.UBO_AMT / DECODE(UT.V_CNT, 0, NULL, UT.V_CNT) ),0))),'-'),'무상') AVG_AMT /* 전월 AS건당 평균비용 */ ,UT.CNT1 /* 전전월 AS건수 */ ,VW1.UBO_AMT UBO_AMT /* 전월 유지보수 계약금액 */ ,VW2.UBO_AMT UBO_AMT1 /* 전전월 유지보수 계약금액 */ ,RANK() OVER (ORDER BY CNT ASC ) as rk1 /* AS건 오름차순 순위 */ ,RANK() OVER (ORDER BY DECODE(UT.DEAL_CODE,'C002',NVL(DECODE(UT.CNT,0,0, ROUND((VW1.UBO_AMT / DECODE(UT.V_CNT, 0, NULL, UT.V_CNT) ),0)),0),0) ASC ) as rk2 /* 건당비용 오름차순 순위*/ FROM ( SELECT IN_TB.CRM_CODE ,IN_TB.CUST_NM ,ROUND(SUM(A_CNT),0) V_CNT ,COUNT(A_CNT) CNT ,( SELECT ROUND(SUM(A_CNT),0) AS CNT1 FROM ( SELECT Z.CUST_CODE, CASE Z.CAUSE_TYPE WHEN 'A001' THEN (SELECT A001_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A002' THEN (SELECT A002_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A003' THEN (SELECT A003_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A004' THEN (SELECT A004_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A005' THEN (SELECT A005_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A006' THEN (SELECT A006_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A007' THEN (SELECT A007_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A008' THEN (SELECT A008_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A009' THEN (SELECT A009_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A010' THEN (SELECT A010_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A011' THEN (SELECT A011_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A012' THEN (SELECT A012_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) WHEN 'A013' THEN (SELECT A013_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, - 2),'YYYY')) ELSE 1 END AS A_CNT FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS(SYSDATE,-2),'YYYYMM') || '%' AND Z.DEL_YN IS NULL ) WHERE IN_TB.CRM_CODE = CUST_CODE GROUP BY CUST_CODE ) CNT1 ,MAX(IN_TB.SEQ) AS SEQ ,MAX(IN_TB.DEAL_CODE) AS DEAL_CODE ,MAX(IN_TB.CUST_GUBUN) AS CUST_GUBUN ,MAX(IN_TB.FOUNDATION_CODE) AS FOUNDATION_CODE FROM ( SELECT A.AS_NO, CASE A.CAUSE_TYPE WHEN 'A001' THEN (SELECT A001_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A002' THEN (SELECT A002_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A003' THEN (SELECT A003_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A004' THEN (SELECT A004_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A005' THEN (SELECT A005_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A006' THEN (SELECT A006_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A007' THEN (SELECT A007_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A008' THEN (SELECT A008_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A009' THEN (SELECT A009_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A010' THEN (SELECT A010_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A011' THEN (SELECT A011_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A012' THEN (SELECT A012_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) WHEN 'A013' THEN (SELECT A013_W FROM VW_AS_CAUSE_WEIGHT WHERE YYYY = TO_CHAR(ADD_MONTHS(SYSDATE, -1),'YYYY')) ELSE 1 END AS A_CNT, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ, B.DEAL_CODE, B.CUST_GUBUN, B.FOUNDATION_CODE FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A INNER JOIN (SELECT CCM.*, COI.DEAL_CODE FROM CRM_CUST_MGT CCM, CRM_CUST_OPERATE_INFO COI WHERE CCM.SEQ = COI.SEQ AND COI.DEAL_CODE IN ('C001','C002')) B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN = 'C005' AND B.CUST_GUBUN = 'C006'
) IN_TB GROUP BY CUST_NM, CRM_CODE UNION ALL SELECT CRM_CODE, CUST_KOR_NAME AS CUST_NM , 0 V_CNT, 0 CNT , 0 CNT1 , SEQ , DEAL_CODE , CUST_GUBUN , FOUNDATION_CODE FROM (SELECT CCM.*, COI.DEAL_CODE FROM CRM_CUST_MGT CCM, CRM_CUST_OPERATE_INFO COI WHERE CCM.SEQ = COI.SEQ AND COI.DEAL_CODE IN ('C001','C002')) WHERE CRM_CODE NOT IN (SELECT CUST_CODE FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') Z WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND Z.DEL_YN IS NULL)
AND CUST_GUBUN IN ('C003' , 'C004') AND CUST_GUBUN = 'C002' AND CUST_GUBUN = 'C001' AND CUST_GUBUN = 'C005' AND CUST_GUBUN = 'C006'
) UT ,( SELECT CRM_CODE, UBO_AMT FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') ) VW1 ,( SELECT CRM_CODE, UBO_AMT FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') ) VW2 WHERE 1=1 AND UT.CRM_CODE = VW1.CRM_CODE(+) AND UT.CRM_CODE = VW2.CRM_CODE(+)
ORDER BY CUST_NM

/* 대쉬보드 거래처 as 분석 */ SELECT UT.SEQ /* CUST_MGT.SEQ */ ,UT.CRM_CODE ,UT.CUST_GUBUN ,NVL((SELECT DISTINCT CODE_NAME FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'CUST' AND P_CODE='CD01' AND CODE = UT.CUST_GUBUN),'-') AS CUST_GUBUN_NM ,UT.FOUNDATION_CODE ,NVL((SELECT DISTINCT CODE_NAME FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'CUST' AND P_CODE='CD08' AND CODE = UT.FOUNDATION_CODE),'-') AS FOUNDATION_CODE_NM ,UT.CUST_NM ,UT.CNT /* 전월 AS건수 */ ,DECODE(UT.DEAL_CODE,'C002',NVL(DECODE(UT.CNT,0,'-', TO_CHAR(ROUND((VW1.UBO_AMT / UT.CNT),0))),'-'),'무상') AVG_AMT /* 전월 AS건당 평균비용 */ ,UT.CNT1 /* 전전월 AS건수 */ ,VW1.UBO_AMT UBO_AMT /* 전월 유지보수 계약금액 */ ,VW2.UBO_AMT UBO_AMT1 /* 전전월 유지보수 계약금액 */ ,RANK() OVER (ORDER BY CNT ASC ) as rk1 /* AS건 오름차순 순위 */ ,RANK() OVER (ORDER BY DECODE(UT.DEAL_CODE,'C002',NVL(DECODE(UT.CNT,0,0, ROUND((VW1.UBO_AMT / UT.CNT),0)),0),0) ASC ) as rk2 /* 건당비용 오름차순 순위*/ FROM ( SELECT IN_TB.CRM_CODE ,IN_TB.CUST_NM , COUNT(CRM_CODE) CNT ,(SELECT COUNT(Z.AS_NO) CNTZ FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND IN_TB.CRM_CODE = Z.CUST_CODE AND Z.DEL_YN IS NULL) CNT1 ,MAX(IN_TB.SEQ) AS SEQ ,MAX(IN_TB.DEAL_CODE) AS DEAL_CODE ,MAX(IN_TB.CUST_GUBUN) AS CUST_GUBUN ,MAX(IN_TB.FOUNDATION_CODE) AS FOUNDATION_CODE FROM ( SELECT A.AS_NO, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ, B.DEAL_CODE, B.CUST_GUBUN, B.FOUNDATION_CODE FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A INNER JOIN (SELECT CCM.*, COI.DEAL_CODE FROM CRM_CUST_MGT CCM, CRM_CUST_OPERATE_INFO COI WHERE CCM.SEQ = COI.SEQ AND COI.DEAL_CODE IN ('C001','C002')) B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN IN ('C005' , 'C006')
) IN_TB GROUP BY CUST_NM, CRM_CODE UNION ALL SELECT CRM_CODE, CUST_KOR_NAME AS CUST_NM , 0 CNT , 0 CNT1 , SEQ , DEAL_CODE , CUST_GUBUN , FOUNDATION_CODE FROM (SELECT CCM.*, COI.DEAL_CODE FROM CRM_CUST_MGT CCM, CRM_CUST_OPERATE_INFO COI WHERE CCM.SEQ = COI.SEQ AND COI.DEAL_CODE IN ('C001','C002')) WHERE CRM_CODE NOT IN (SELECT CUST_CODE FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') Z WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND Z.DEL_YN IS NULL)
AND CUST_GUBUN IN ('C003' , 'C004') AND CUST_GUBUN = 'C002' AND CUST_GUBUN = 'C001' AND CUST_GUBUN IN ('C005' , 'C006')
) UT ,( SELECT CRM_CODE, UBO_AMT FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') ) VW1 ,( SELECT CRM_CODE, UBO_AMT FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') ) VW2 WHERE 1=1 AND UT.CRM_CODE = VW1.CRM_CODE(+) AND UT.CRM_CODE = VW2.CRM_CODE(+)
ORDER BY CUST_NM

SELECT T_TB.* , 'A' GUBUN FROM ( SELECT OUT_TB.*, RANK() OVER (ORDER BY CNT DESC ) as rk FROM ( SELECT IN_TB.CRM_CODE ,IN_TB.CUST_NM , COUNT(CRM_CODE) CNT ,(SELECT COUNT(Z.AS_NO) CNTZ FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND IN_TB.CRM_CODE = Z.CUST_CODE AND Z.DEL_YN IS NULL) CNT1 ,MAX(IN_TB.SEQ) AS SEQ FROM ( SELECT A.AS_NO, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ FROM CRM_AS_MGT A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN IN ('C005' , 'C006')
) IN_TB GROUP BY CUST_NM, CRM_CODE ) OUT_TB ) T_TB WHERE RK = 1 UNION ALL SELECT T_TB.* , 'B' GUBUN FROM ( SELECT OUT_TB.*, RANK() OVER (ORDER BY CNT ASC ) as rk FROM ( SELECT IN_TB.CRM_CODE, IN_TB.CUST_NM, COUNT(CRM_CODE) CNT ,(SELECT COUNT(Z.AS_NO) CNTZ FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND IN_TB.CRM_CODE = Z.CUST_CODE AND Z.DEL_YN IS NULL ) CNT1 ,MAX(IN_TB.SEQ) AS SEQ FROM ( SELECT A.AS_NO, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ FROM CRM_AS_MGT A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN IN ('C005' , 'C006')
) IN_TB GROUP BY CUST_NM, CRM_CODE ) OUT_TB ) T_TB WHERE RK = 1 UNION ALL SELECT T_TB.* , 'C' GUBUN FROM ( SELECT OUT_TB.*,RANK() OVER (ORDER BY (CNT - CNT1) DESC ) as rk FROM ( SELECT IN_TB.CRM_CODE, IN_TB.CUST_NM, COUNT(CRM_CODE) CNT ,(SELECT COUNT(Z.AS_NO) CNTZ FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND IN_TB.CRM_CODE = Z.CUST_CODE AND Z.DEL_YN IS NULL) CNT1 ,MAX(IN_TB.SEQ) AS SEQ FROM ( SELECT A.AS_NO, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ FROM CRM_AS_MGT A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN IN ('C005' , 'C006')
) IN_TB GROUP BY CUST_NM, CRM_CODE ) OUT_TB ) T_TB WHERE RK = 1 UNION ALL SELECT T_TB.* , 'D' GUBUN FROM ( SELECT OUT_TB.*, RANK() OVER (ORDER BY (CNT1 - CNT) DESC) as rk FROM ( SELECT IN_TB.CRM_CODE, IN_TB.CUST_NM, COUNT(CRM_CODE) CNT ,(SELECT COUNT(Z.AS_NO) CNTZ FROM CRM_AS_MGT Z WHERE Z.ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND IN_TB.CRM_CODE = Z.CUST_CODE AND Z.DEL_YN IS NULL) CNT1 ,MAX(IN_TB.SEQ) AS SEQ FROM ( SELECT A.AS_NO, B.CRM_CODE, B.CUST_KOR_NAME AS CUST_NM, B.SEQ FROM CRM_AS_MGT A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.CRM_CODE WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.DEL_YN IS NULL
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN IN ('C005' , 'C006')
) IN_TB GROUP BY CUST_NM, CRM_CODE ) OUT_TB ) T_TB WHERE RK = 1 UNION ALL SELECT CRM_CODE, CUST_KOR_NAME AS CUST_NM , 0 CNT , 0 CNT1 , SEQ , 1 PK , 'E' GUBUN FROM CRM_CUST_MGT WHERE CRM_CODE NOT IN (SELECT CUST_CODE FROM CRM_AS_MGT Z WHERE ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND Z.DEL_YN IS NULL)
AND CUST_GUBUN IN ('C003' , 'C004') AND CUST_GUBUN = 'C002' AND CUST_GUBUN = 'C001' AND CUST_GUBUN IN ('C005' , 'C006')

SELECT B.SEQ, A.CRM_CODE, A.MISU_AMT, B.CUST_KOR_NAME FROM ( SELECT CRM_CODE, AMT MISU_AMT FROM ( SELECT DISTINCT ERP_CODE,CRM_CODE FROM CRM_CUST_MGT_HIST ) X, (SELECT T1.CUST_CD -- 거래처코드 , SUM(T1.CURRENCY_AMT + T1.VAT_AMT - COLL_CURRENCY_AMT) AS AMT FROM KYERP.TB_SD_RECEIVABLE_DTL T1 WHERE 1=1 AND T1.CURRENCY = '00001' AND T1.SALE_TYPE = '00001' AND T1.COLL_END_YN = 'N' AND T1.STATUS = '00002' -- 매출확정 AND T1.RV_SLIP_NUMB IS NOT NULL -- 전표발생분 AND SUBSTR(SALE_DT,1,6) <= TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMM') AND ITEM_CD IN('C300000001','H000000110') GROUP BY T1.CUST_CD
) Y WHERE X.ERP_CODE = Y.CUST_CD(+)
) A
INNER JOIN (SELECT CM.* FROM CRM_CUST_MGT CM, CRM_CUST_OPERATE_INFO COI WHERE CM.SEQ = COI.SEQ AND COI.DEAL_CODE NOT IN ('C003','C004')) B ON A.CRM_CODE = B.CRM_CODE INNER JOIN CRM_CUST_MAINTENANCE_HIST D ON B.SEQ = D.SEQ WHERE A.MISU_AMT > 0 AND D.BILL_CODE = 'C001'
AND B.CUST_GUBUN IN ('C003' , 'C004') AND B.CUST_GUBUN = 'C002' AND B.CUST_GUBUN = 'C001' AND B.CUST_GUBUN = 'C005' AND B.CUST_GUBUN = 'C006'
ORDER BY A.MISU_AMT DESC

SELECT ROUND(AVG_DAY1,0) CNT_BY_DAY1 /* 전월 일평균 AS 건수 */ ,ROUND(AVG_DAY2,0) CNT_BY_DAY2 /* 전전월 일평균 AS 건수 */ ,DECODE(AVG_DAY1,0,0,DECODE(AVG_DAY2,0,0,ROUND((AVG_DAY1 * 100 / AVG_DAY2),1) - 100)) AS CNT_RATE /* 전전월 대비 건수 증가율 */ ,ROUND(AVG_AMT1) AMT_BY_DAY1 /* 전월 AS 건당 평균 비용 */ ,ROUND(AVG_AMT2) AMT_BY_DAY2 /* 전전월 AS 건당 평균 비용 */ ,DECODE(AVG_AMT1,0,0,DECODE(AVG_AMT2,0,0,ROUND((AVG_AMT1 * 100 / AVG_AMT2),1) - 100)) AS AMT_RATE /* 전전월 대비 AS 건당 평균 비용 증가율 */ FROM ( SELECT ( SELECT COUNT(A.AS_NO) AS CNT FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A ,( SELECT A.CRM_CODE, B.DEAL_CODE FROM CRM_CUST_MGT A, CRM_CUST_OPERATE_INFO B WHERE A.SEQ = B.SEQ AND B.DEAL_CODE IN ('C001','C002')
AND A.CUST_GUBUN IN ('C003' , 'C004') AND A.CUST_GUBUN = 'C002' AND A.CUST_GUBUN = 'C001' AND A.CUST_GUBUN IN ('C005' , 'C006')
) TB1 WHERE 1=1 AND ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.CUST_CODE = TB1.CRM_CODE ) / ( SELECT TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(SYSDATE, -1)),'DD')) FROM DUAL ) AS AVG_DAY1, ( SELECT COUNT(A.AS_NO) AS CNT FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A ,( SELECT A.CRM_CODE, B.DEAL_CODE FROM CRM_CUST_MGT A, CRM_CUST_OPERATE_INFO B WHERE A.SEQ = B.SEQ AND B.DEAL_CODE IN ('C001','C002')
AND A.CUST_GUBUN IN ('C003' , 'C004') AND A.CUST_GUBUN = 'C002' AND A.CUST_GUBUN = 'C001' AND A.CUST_GUBUN IN ('C005' , 'C006')
) TB1 WHERE 1=1 AND ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND A.CUST_CODE = TB1.CRM_CODE ) / ( SELECT TO_NUMBER(TO_CHAR(LAST_DAY(ADD_MONTHS(SYSDATE, -1)),'DD')) FROM DUAL ) AS AVG_DAY2, ( SELECT NVL(SUM(UBO_AMT),0) AS UBO_SUM FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN IN ('C003' , 'C004'))
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN = 'C002')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN = 'C001')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN IN ('C005' , 'C006'))
) / ( SELECT DECODE(COUNT(A.AS_NO),0,1,COUNT(A.AS_NO)) AS CNT FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A ,( SELECT A.CRM_CODE, B.DEAL_CODE FROM CRM_CUST_MGT A, CRM_CUST_OPERATE_INFO B WHERE A.SEQ = B.SEQ AND B.DEAL_CODE IN ('C001','C002')
AND A.CUST_GUBUN IN ('C003' , 'C004') AND A.CUST_GUBUN = 'C002' AND A.CUST_GUBUN = 'C001' AND A.CUST_GUBUN IN ('C005' , 'C006')
) TB1 WHERE 1=1 AND ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-1) , 'YYYYMM') || '%' AND A.CUST_CODE = TB1.CRM_CODE ) AS AVG_AMT1, ( SELECT NVL(SUM(UBO_AMT),0) AS UBO_SUM FROM VW_CUST_BILL_HIST WHERE SALE_YM = TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN IN ('C003' , 'C004'))
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN = 'C002')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN = 'C001')
AND CRM_CODE IN (SELECT CRM_CODE FROM CRM_CUST_MGT WHERE CUST_GUBUN IN ('C005' , 'C006'))
) / ( SELECT DECODE(COUNT(A.AS_NO),0,1,COUNT(A.AS_NO)) AS CNT FROM (SELECT AM.* FROM CRM_AS_MGT AM WHERE AM.PROC_STATUS = 'C005') A ,( SELECT A.CRM_CODE, B.DEAL_CODE FROM CRM_CUST_MGT A, CRM_CUST_OPERATE_INFO B WHERE A.SEQ = B.SEQ AND B.DEAL_CODE IN ('C001','C002')
AND A.CUST_GUBUN IN ('C003' , 'C004') AND A.CUST_GUBUN = 'C002' AND A.CUST_GUBUN = 'C001' AND A.CUST_GUBUN IN ('C005' , 'C006')
) TB1 WHERE 1=1 AND ACCEPT_DT LIKE TO_CHAR(ADD_MONTHS( SYSDATE ,-2) , 'YYYYMM') || '%' AND A.CUST_CODE = TB1.CRM_CODE ) AS AVG_AMT2 FROM DUAL )

WITH BASE_TB AS ( SELECT CMH.MTAC_CODE, SUBSTR(CMH.CONTRACT_DT,1,6) AS CONTRACT_DT, CMH.MTAC_END_DT FROM CRM_CUST_MAINTENANCE_HIST_CC CMH, CRM_CUST_MGT CM WHERE CMH.SEQ = CM.SEQ AND CMH.BILL_CODE = 'C004' AND CMH.MTAC_CODE IS NOT NULL
AND CM.CUST_GUBUN IN ('C003' , 'C004') AND CM.CUST_GUBUN = 'C002' AND CM.CUST_GUBUN = 'C001' AND CM.CUST_GUBUN = 'C005' AND CM.CUST_GUBUN = 'C006'
) SELECT TO_CHAR(ADD_MONTHS(SYSDATE,-5),'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(ADD_MONTHS(SYSDATE,-5),'YYYYMM') AND MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE,-5),'YYYYMMDD') UNION ALL SELECT TO_CHAR(ADD_MONTHS(SYSDATE,-4),'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(ADD_MONTHS(SYSDATE,-4),'YYYYMM') AND MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE,-4),'YYYYMMDD') UNION ALL SELECT TO_CHAR(ADD_MONTHS(SYSDATE,-3),'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(ADD_MONTHS(SYSDATE,-3),'YYYYMM') AND MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE,-3),'YYYYMMDD') UNION ALL SELECT TO_CHAR(ADD_MONTHS(SYSDATE,-2),'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(ADD_MONTHS(SYSDATE,-2),'YYYYMM') AND MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE,-2),'YYYYMMDD') UNION ALL SELECT TO_CHAR(ADD_MONTHS(SYSDATE,-1),'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMM') AND MTAC_END_DT >= TO_CHAR(ADD_MONTHS(SYSDATE,-1),'YYYYMMDD') UNION ALL SELECT TO_CHAR(SYSDATE,'MM') AS YYYYMM ,SUM(DECODE(MTAC_CODE,'C008',1,0)) AS C1 ,SUM(DECODE(MTAC_CODE,'C009',1,0)) AS C2 ,SUM(DECODE(MTAC_CODE,'C010',1,0)) AS C3 ,SUM(DECODE(MTAC_CODE,'C011',1,0)) AS C4 ,COUNT(MTAC_CODE) TOT FROM BASE_TB WHERE CONTRACT_DT <= TO_CHAR(SYSDATE,'YYYYMM') AND MTAC_END_DT >= TO_CHAR(SYSDATE,'YYYYMMDD')

SELECT A.AS_NO ,A.W_ID ,(SELECT EMP_NM FROM CRM_EMP_MGT E WHERE E.EMP_NO= A.W_ID) AS W_NM ,A.W_CONTENT ,TO_CHAR(A.W_DATE,'YYYY-MM-DD HH24:MI:SS') AS W_DATE ,A.W_GUBUN ,A.ATTACH_SEQ ,M.APPLY_NM ,M.APPLY_ID ,M.CALL_CONTENT ,M.CUST_CODE ,DECODE( TO_CHAR(A.W_DATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'YYYYMMDD'), '1', '0') AS TODAY_GUBUN ,M.CALL_CONTENT FROM CRM_AS_MGT_ANSWER A, CRM_AS_MGT M WHERE 1=1 AND TO_CHAR(A.W_DATE,'YYYYMMDD') BETWEEN #{asw_str_dt} AND #{asw_end_dt} AND A.W_GUBUN = 'A' AND A.AS_NO = M.AS_NO AND M.CUST_CODE = #{cust_code}
AND M.APPLY_ID = #{user_id}
ORDER BY A.W_DATE
